// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.IntakeItem) predicate.IntakeItem {
	return predicate.IntakeItem(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.IntakeItem) predicate.IntakeItem {
	return predicate.IntakeItem(sql.NotPredicates(p))
}
